  jobs: {
    "notifications.dispatch": {
      "schedule": "queue worker",
      "does": "Render and send queued deliveries per channel with provider rate limits; mark sent"
    },
    "notifications.retry": {
      "schedule": "every minute",
      "does": "Re-send retrying deliveries whose nextAttemptAt passed; give up after maxDeliveryAttempts (notifications.delivery.failed)"
    },
    "notifications.send-scheduled": {
      "schedule": "every minute",
      "does": "Send scheduled notices due now (dispatch deadline reminders 4 h before, drop-off reminders, approval due reminders)"
    },
    "notifications.send-broadcasts": {
      "schedule": "every minute",
      "does": "Start scheduled broadcasts, resolve consenting recipients, respect quiet hours for SMS and push, publish notifications.broadcast.sent"
    },
    "notifications.staff-digest": {
      "schedule": "daily at the start of business hours",
      "does": "Email the daily digest to staff who chose it"
    },
    "notifications.purge": {
      "schedule": "daily",
      "does": "Delete notices older than noticeRetentionMonths and delivery rows older than deliveryLogRetentionDays; expire unresolved action notices whose records closed"
    }
  },
  settings: {
    "noticeRetentionMonths": {
      "default": 12,
      "desc": "Notices are kept for 12 months (seller inbox copy)"
    },
    "deliveryLogRetentionDays": {
      "default": 180,
      "desc": "Delivery log retention"
    },
    "maxDeliveryAttempts": {
      "default": 6,
      "desc": "Attempts before a delivery fails"
    },
    "retryBackoffMinutes": {
      "default": [
        1,
        5,
        15,
        60,
        240
      ],
      "desc": "Delay before each retry"
    },
    "dedupeWindowMinutes": {
      "default": 30,
      "desc": "Same dedupeKey and recipient is sent once in this window"
    },
    "senders": {
      "default": {
        "orders": "Marketly Orders <orders@marketly.example>",
        "account": "Marketly <no-reply@marketly.example>",
        "sellers": "Marketly Seller Center <sellers@marketly.example>",
        "promotions": "Marketly Deals <deals@marketly.example>"
      },
      "desc": "From addresses per topic family"
    },
    "replyDomain": {
      "default": "reply.marketly.example",
      "desc": "Domain for reply-to tokens on case and message emails"
    },
    "testSendDomains": {
      "default": [
        "marketly.example"
      ],
      "desc": "Test sends only to these domains"
    },
    "sellerDispatchReminderHours": {
      "default": 4,
      "desc": "Hours before the dispatch deadline for the seller reminder (scheduled when shipping or orders call schedule)"
    },
    "promotionalQuietHours": {
      "default": {
        "from": "21:00",
        "to": "08:00"
      },
      "desc": "No promotional SMS or push in this local window"
    }
  },
  errorCodes: {
    "GROUP_LOCKED": {
      "status": 409,
      "meaning": "That topic group cannot be changed for this member (essential for the owner, or owner-only)."
    },
    "CHANNEL_LOCKED": {
      "status": 409,
      "meaning": "In-app cannot be turned off for essential topics."
    },
    "CHANNEL_NOT_AVAILABLE": {
      "status": 409,
      "meaning": "The channel is planned for a later phase (SMS 2, push 3)."
    },
    "DRAFT_EXISTS": {
      "status": 409,
      "meaning": "This template already has a draft (details.versionId)."
    },
    "TEMPLATE_INVALID": {
      "status": 422,
      "meaning": "Blocking validation issues, e.g. missing required link variable. details.issues."
    },
    "TEST_RECIPIENT_NOT_ALLOWED": {
      "status": 403,
      "meaning": "Test sends only go to staff addresses (testSendDomains)."
    },
    "ADDRESS_SUPPRESSED": {
      "status": 409,
      "meaning": "The address is suppressed; remove the suppression first."
    },
    "NOT_RETRYABLE": {
      "status": 409,
      "meaning": "Sensitive content (codes, links) expired; the person must request a new one."
    },
    "TOPIC_NOT_PROMOTIONAL": {
      "status": 400,
      "meaning": "Broadcasts can only use promotional topics."
    }
  },
